import random

def quickselect(arr: list[int], k: int) -> int:
    """Find the kth smallest element in arr using the Quickselect algorithm.

    Args:
        arr: List of integers.
        k: Index of the element to find (0-based).

    Returns:
        The kth smallest element in arr.

    Raises:
        ValueError: If k is out of bounds.
    """
    if k < 0 or k >= len(arr):
        raise ValueError("k is out of bounds")

    left, right = 0, len(arr) - 1

    while True:
        # Choose a random pivot to avoid worst-case on sorted data
        pivot_index = random.randint(left, right)
        pivot_value = arr[pivot_index]
        arr[pivot_index], arr[right] = arr[right], arr[pivot_index]

        # Partition: move elements smaller than pivot to the left
        store_index = left
        for i in range(left, right):
            if arr[i] < pivot_value:
                arr[store_index], arr[i] = arr[i], arr[store_index]
                store_index += 1

        # Place pivot in its final sorted position
        arr[store_index], arr[right] = arr[right], arr[store_index]
        pivot_index = store_index

        if k == pivot_index:
            return arr[k]
        elif k < pivot_index:
            right = pivot_index - 1
        else:
            left = pivot_index + 1
