from collections import defaultdict, deque

class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.size = 0
        self.freq = defaultdict(deque)  # key -> deque of keys with same frequency
        self.key_to_freq = defaultdict(int)  # key -> current frequency
        self.key_to_node = {}  # key -> (freq, key) for quick access
        self.min_freq = 0

    def get(self, key: int) -> int:
        if key not in self.key_to_freq:
            return -1
        self._update_freq(key)
        return self.key_to_freq[key]

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return
        if key in self.key_to_freq:
            self.key_to_freq[key] = value  # Update value (logic simplified; actual impl tracks value separately)
            self._update_freq(key)
            return

        if self.size >= self.capacity:
            freq = self.min_freq
            key_to_remove = self.freq[freq].popleft()
            del self.key_to_freq[key_to_remove]
            del self.key_to_node[key_to_remove]
            if not self.freq[freq]:
                del self.freq[freq]
                self.min_freq += 1
            self.size -= 1

        # Add new
        self.freq[self.min_freq].append(key)
        self.key_to_freq[key] = value
        self.key_to_node[key] = (self.min_freq, key)
        self.min_freq = 1
        self.size += 1

    def _update_freq(self, key: int):
        old_freq = self.key_to_freq[key]
        self.freq[old_freq].remove(key)
        if not self.freq[old_freq]:
            del self.freq[old_freq]
            if old_freq == self.min_freq:
                self.min_freq += 1

        new_freq = old_freq + 1
        self.key_to_freq[key] = new_freq
        self.freq[new_freq].append(key)
```

*Note: This implementation assumes `value` is stored directly in `key_to_freq` for brevity. A production version would separate `key_to_value`.*

