from typing import Optional

class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.size = 0
        self.freq_map: dict[int, dict[int, int]] = defaultdict(dict)  # freq -> {key: count}
        self.key_freq: dict[int, int] = {}  # key -> freq
        self.key_val: dict[int, int] = {}   # key -> value
        self.min_freq = 0

    def get(self, key: int) -> int:
        if key not in self.key_val:
            return -1
        self._update_freq(key)
        return self.key_val[key]

    def put(self, key: int, value: int) -> None:
        if self.capacity <= 0:
            return
        if key in self.key_val:
            self.key_val[key] = value
            self._update_freq(key)
            return

        if self.size == self.capacity:
            self._evict()

        self.key_val[key] = value
        self.key_freq[key] = 1
        self.freq_map[1][key] = 1
        self.min_freq = 1
        self.size += 1

    def _update_freq(self, key: int) -> None:
        old_freq = self.key_freq[key]
        new_freq = old_freq + 1
        self.freq_map[old_freq].pop(key)
        if not self.freq_map[old_freq]:
            del self.freq_map[old_freq]
            if old_freq == self.min_freq:
                self.min_freq = new_freq
        self.key_freq[key] = new_freq
        self.freq_map[new_freq][key] = 1

    def _evict(self) -> None:
        if not self.freq_map[self.min_freq]:
            return
        key = next(iter(self.freq_map[self.min_freq]))
        del self.key_val[key]
        del self.key_freq[key]
        del self.freq_map[self.min_freq][key]
        if self.min_freq in self.freq_map and not self.freq_map[self.min_freq]:
            del self.freq_map[self.min_freq]
        self.size -= 1
