def compute_lps(pattern: str) -> list[int]:
    """Compute the longest proper prefix which is also a suffix for each prefix of pattern."""
    m = len(pattern)
    lps = [0] * m
    length = 0
    i = 1
    while i < m:
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1
    return lps

def kmp_search(text: str, pattern: str) -> list[int]:
    """Return all start indices where pattern occurs in text using KMP."""
    if not pattern:
        return []
    if len(pattern) > len(text):
        return []

    lps = compute_lps(pattern)
    i = j = 0  # i: text index, j: pattern index
    occurrences = []
    while i < len(text):
        if text[i] == pattern[j]:
            i += 1
            j += 1
            if j == len(pattern):
                occurrences.append(i - j)
                j = lps[j - 1]
        else:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1
    return occurrences
```

