from typing import List, Optional, Set, Tuple

def topological_sort(graph: List[List[int]]) -> Optional[List[int]]:
    """
    Performs a topological sort on a directed graph.
    Returns the sorted list of nodes, or None if a cycle exists.

    Args:
        graph: Adjacency list where graph[i] contains the neighbors of node i.
               Nodes are assumed to be 0-indexed integers.

    Returns:
        A list of nodes in topologically sorted order, or None if a cycle is detected.
    """
    n = len(graph)
    in_degree = [0] * n
    for u in graph:
        for v in u:
            in_degree[v] += 1

    queue = [i for i in range(n) if in_degree[i] == 0]
    result = []

    while queue:
        u = queue.pop(0)
        result.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(result) != n:
        return None  # Cycle detected
    return result
